/* ============================================================
   选址决策台 · styles（compact 工具面 · 信号优先于装饰）
   ============================================================ */
:root {
  --bg: #eef2f6;
  --panel: #ffffff;
  --ink: #0f172a;
  --sub: #64748b;
  --faint: #94a3b8;
  --line: #e2e8f0;
  --row-alt: #f8fafc;
  --acc: #0f766e;          /* 主色 teal-700 */
  --acc-deep: #134e4a;
  --acc-soft: #f0fdfa;
  --acc-line: #99f6e4;
  --best: #15803d;
  --best-bg: #f0fdf4;
  --lead: #b45309;
  --lead-bg: #fffbeb;
  --lock: #1e293b;
}
* { box-sizing: border-box; margin: 0; }
html, body { height: 100%; }
body {
  font: 13px/1.45 "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  color: var(--ink);
  background: var(--bg);
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 10px;
  padding: 10px 12px;
  min-height: 100vh;
}

/* ---------- 通用 ---------- */
button { font: inherit; cursor: pointer; }
:focus-visible { outline: 2px solid var(--acc); outline-offset: 2px; border-radius: 4px; }
kbd {
  font: 11px/1 inherit; border: 1px solid var(--line); border-bottom-width: 2px;
  border-radius: 4px; padding: 1px 4px; background: #fff; color: var(--sub);
}
.panel-h {
  display: flex; align-items: center; gap: 8px;
  font-size: 12px; font-weight: 600; letter-spacing: .02em;
  padding: 8px 12px; border-bottom: 1px solid var(--line);
}
.panel-sub { font-weight: 400; color: var(--faint); font-size: 11px; }
.chip {
  font-size: 10px; padding: 1px 7px; border-radius: 999px;
  background: var(--lead-bg); border: 1px solid #fcd34d; color: #92400e;
}
.btn-ghost {
  margin-left: auto; font-size: 11px; padding: 2px 9px; border-radius: 6px;
  border: 1px solid var(--line); background: #fff; color: var(--sub);
}
.btn-ghost:hover { background: var(--row-alt); }

/* ---------- 头部 ---------- */
#region-header {
  display: flex; align-items: center; gap: 16px;
  background: var(--panel); border: 1px solid var(--line); border-radius: 10px;
  padding: 8px 14px;
}
.brand { display: flex; align-items: center; gap: 7px; font-weight: 700; font-size: 13px; white-space: nowrap; }
.brand-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--acc); }
.head-main h1 { font-size: 15px; }
.lead { font-size: 12px; color: var(--sub); }
.kbd-hints {
  margin-left: auto; display: flex; flex-direction: column; gap: 3px;
  font-size: 11px; color: var(--faint); white-space: nowrap;
}
.kbd-hints span { display: flex; gap: 4px; align-items: center; justify-content: flex-end; }

/* ---------- 主区 ---------- */
#region-main {
  display: grid; grid-template-columns: minmax(340px, 31%) 1fr;
  gap: 10px; min-height: 0;
}
#region-map, #region-matrix, #region-weights {
  background: var(--panel); border: 1px solid var(--line); border-radius: 10px;
  overflow: hidden; display: flex; flex-direction: column;
}
#region-map svg { width: 100%; height: auto; flex: 0 1 auto; min-height: 0; }

/* ---------- 地图 ---------- */
.river { fill: #dbeafe; }
.river-label { fill: #93c5fd; font-size: 12px; letter-spacing: 6px; }
.road { stroke: #e2e8f0; stroke-width: 10; fill: none; stroke-linecap: round; }
.bridge { stroke: #94a3b8; stroke-width: 7; }
.map-micro { font-size: 10px; fill: var(--faint); }
.district-label { font-size: 13px; font-weight: 700; fill: #cbd5e1; letter-spacing: 6px; }
.m-anchor circle { fill: #eef2ff; stroke: #6366f1; stroke-width: 1.6; stroke-dasharray: 5 4; }
.m-anchor text { font-size: 11px; font-weight: 600; fill: #4f46e5; }
.m-anchor .anchor-sub { font-size: 9px; fill: #818cf8; font-weight: 400; }
.m-metro polyline { fill: none; stroke: #f59e0b; stroke-width: 4.5; stroke-linejoin: round; transition: stroke-width .12s; }
.m-metro .stn circle { fill: #fff; stroke: #d97706; stroke-width: 2.5; }
.m-metro .stn text { font-size: 10px; fill: #92400e; }
.m-metro.hot polyline { stroke-width: 7; filter: drop-shadow(0 0 3px rgba(245,158,11,.65)); }
.m-flow path { fill: none; stroke-width: 7; stroke-dasharray: 1 10; stroke-linecap: round; transition: stroke-width .12s; }
.m-flow .weekend { stroke: #93c5fd; } .m-flow .weekday { stroke: #a5b4fc; }
.m-flow .flow-label { font-size: 10px; fill: var(--sub); }
.m-flow.hot path { stroke-width: 10; filter: drop-shadow(0 0 3px rgba(99,102,241,.5)); }
.m-rivals .rival circle { fill: #334155; transition: r .12s; }
.m-rivals.hot .rival circle { fill: #0f172a; r: 7; filter: drop-shadow(0 0 3px rgba(15,23,42,.5)); }
svg.has-hot > :not(.hot):not(#pins):not(defs):not(.river):not(.road):not(.bridge):not(.river-label):not(.map-micro):not(.district-label) { opacity: .4; transition: opacity .12s; }
svg line, svg path, svg circle, svg text { transition: opacity .12s; }
#pins .pin { cursor: pointer; }
.pin-halo { fill: var(--acc); opacity: 0; transition: opacity .12s, r .12s; }
.pin.is-lead .pin-halo { opacity: .22; }
.pin.is-sel .pin-halo { opacity: .3; r: 24; }
.pin-dot { fill: var(--acc); stroke: #fff; stroke-width: 2.5; }
.pin.is-sel .pin-dot { fill: var(--acc-deep); }
.pin.is-locked .pin-dot { stroke: var(--lock); stroke-width: 4; }
.pin-key { font-size: 12px; font-weight: 700; fill: #fff; pointer-events: none; }
.pin-name { font-size: 11px; font-weight: 600; fill: var(--ink); paint-order: stroke; stroke: #fff; stroke-width: 3px; }
#pins .pin:focus-visible { outline: none; }
#pins .pin:focus-visible .pin-dot { stroke: var(--lock); stroke-width: 4; }
#walk-line { stroke: var(--acc); stroke-width: 2; stroke-dasharray: 4 4; }
.walk-label { font-size: 10px; font-weight: 600; fill: var(--acc-deep); paint-order: stroke; stroke: #fff; stroke-width: 3px; }
.map-info { font-size: 12px; color: var(--sub); padding: 6px 12px 2px; }
.map-info strong { color: var(--acc-deep); }
#legend {
  list-style: none; display: flex; flex-wrap: wrap; gap: 5px 14px;
  padding: 6px 12px 10px; font-size: 11px; color: var(--sub);
}
#legend li { display: flex; align-items: center; gap: 5px; }
#legend i { display: inline-block; }
.lg-pin { width: 10px; height: 10px; border-radius: 50%; background: var(--acc); }
.lg-rival { width: 9px; height: 9px; border-radius: 50%; background: #334155; }
.lg-metro { width: 14px; height: 3px; border-radius: 2px; background: #f59e0b; }
.lg-anchor { width: 10px; height: 10px; border-radius: 50%; border: 1.5px dashed #6366f1; background: #eef2ff; }
.lg-flow { width: 14px; height: 0; border-top: 3px dotted #93c5fd; }
.lg-river { width: 14px; height: 8px; border-radius: 2px; background: #dbeafe; }

/* ---------- 右列 ---------- */
#region-right { display: flex; flex-direction: column; gap: 10px; min-height: 0; }
#region-matrix { flex: 1 1 auto; min-height: 0; }
#matrix-wrap { overflow: auto; flex: 1; }

/* 表格（比较矩阵） */
table { width: 100%; border-collapse: collapse; }
th, td { padding: 6px 10px; text-align: left; vertical-align: middle; }
thead th {
  position: sticky; top: 0; z-index: 2; background: var(--row-alt);
  border-bottom: 1px solid var(--line); font-weight: 600;
}
col.c-label { width: 128px; }
th.rowh { font-size: 12px; color: var(--sub); font-weight: 600; }
th.rowh .u { display: block; font-size: 10px; color: var(--faint); font-weight: 400; }
tbody tr { border-bottom: 1px solid #f1f5f9; }
tbody tr[data-crit] { cursor: default; }
tbody tr[data-crit]:hover { background: var(--row-alt); }
td .val { font-variant-numeric: tabular-nums; }
.badge-best {
  display: inline-block; margin-left: 6px; font-size: 10px; line-height: 1;
  padding: 2px 5px; border-radius: 5px; color: var(--best); background: var(--best-bg);
  border: 1px solid #bbf7d0; font-weight: 700; vertical-align: 1px;
}
.bar { height: 4px; border-radius: 2px; background: var(--line); margin-top: 4px; max-width: 150px; }
.bar i { display: block; height: 100%; border-radius: 2px; background: var(--acc); opacity: .75; }
td.best .bar i { background: var(--best); opacity: 1; }
.cell-arch { font-size: 12px; color: var(--sub); }
.cell-note { font-size: 12px; color: var(--sub); line-height: 1.5; }

/* 列状态：选中 / 锁定 / 列头按钮 */
th.col, td { transition: background .12s; }
.is-sel { background: var(--acc-soft); }
th.col.is-sel { box-shadow: inset 0 -2px 0 var(--acc); }
.is-locked-col th.col, .is-locked-col td { background: #f1f5f9; }
.is-locked-col .is-sel, .is-locked-col th.col.is-sel { background: var(--acc-soft); box-shadow: inset 0 0 0 2px var(--acc-deep); }
.col-btn {
  all: unset; display: block; width: 100%; cursor: pointer; border-radius: 6px; padding: 2px 4px;
}
.col-btn:hover { background: #f1f5f9; }
.col-btn .site-key {
  display: inline-flex; width: 18px; height: 18px; border-radius: 50%;
  background: var(--acc); color: #fff; font-size: 11px; font-weight: 700;
  align-items: center; justify-content: center; margin-right: 6px; vertical-align: -4px;
}
.col-btn .site-name { font-size: 13px; }
.col-btn .site-addr { display: block; font-size: 10px; color: var(--faint); font-weight: 400; margin-top: 1px; }
.chip-lead {
  display: inline-block; margin-left: 6px; font-size: 10px; line-height: 1; padding: 2px 5px;
  border-radius: 5px; background: var(--lead-bg); border: 1px solid #fcd34d; color: var(--lead); font-weight: 700;
}
.chip-lock { display: inline-block; margin-left: 6px; font-size: 10px; padding: 2px 5px; border-radius: 5px; background: var(--lock); color: #fff; font-weight: 700; }
/* 契合分行 */
tr.row-fit td, tr.row-fit th { background: var(--acc-soft); border-top: 1px solid var(--acc-line); border-bottom: 1px solid var(--acc-line); }
.fit-score { font-size: 19px; font-weight: 800; color: var(--acc-deep); font-variant-numeric: tabular-nums; }
.fit-rank {
  display: inline-flex; width: 18px; height: 18px; border-radius: 50%; font-size: 11px; font-weight: 700;
  align-items: center; justify-content: center; margin-left: 7px; vertical-align: 2px;
  background: #e2e8f0; color: var(--sub);
}
tr.row-fit td.rank1 .fit-rank { background: var(--acc); color: #fff; }
tr.row-fit td.rank1 .fit-score { color: var(--acc-deep); }
.fit-empty { font-size: 12px; color: var(--faint); }

/* ---------- 权重轨 ---------- */
#region-weights { flex: 0 0 auto; }
#w-chip { margin-left: 2px; }
#weights {
  display: grid; grid-template-columns: 1fr 1fr; gap: 4px 18px; padding: 8px 12px 4px;
}
.w-item { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 2px 8px; }
.w-item label { font-size: 12px; color: var(--ink); font-weight: 600; cursor: pointer; }
.w-item .w-unit { font-size: 10px; color: var(--faint); font-weight: 400; margin-left: 4px; }
.w-item output { font-size: 12px; font-weight: 700; color: var(--acc-deep); font-variant-numeric: tabular-nums; }
.w-item input[type="range"] { grid-column: 1 / -1; width: 100%; height: 18px; accent-color: var(--acc); cursor: ew-resize; }
.w-hint { font-size: 11px; color: var(--faint); padding: 2px 12px 10px; }

/* ---------- 结论条 ---------- */
#region-verdict {
  background: var(--panel); border: 1px solid var(--line); border-radius: 10px;
  display: flex; align-items: center; gap: 14px; padding: 9px 14px; min-height: 46px;
}
.v-leader { font-size: 13px; }
.v-leader strong { color: var(--acc-deep); }
.v-detail { font-size: 12px; color: var(--sub); }
.v-detail b { color: var(--ink); }
.v-actions { margin-left: auto; display: flex; gap: 8px; }
.btn-primary {
  border: 1px solid var(--acc-deep); background: var(--acc); color: #fff;
  border-radius: 8px; padding: 7px 16px; font-weight: 700; font-size: 13px;
}
.btn-primary:hover { background: var(--acc-deep); }
.btn-primary[disabled] { opacity: .45; cursor: not-allowed; }
.btn-locked {
  border: 1px solid var(--lock); background: var(--lock); color: #fff;
  border-radius: 8px; padding: 7px 16px; font-weight: 700; font-size: 13px;
}
.btn-unlock {
  border: 1px solid var(--line); background: #fff; color: var(--sub);
  border-radius: 8px; padding: 7px 12px; font-size: 12px;
}
.btn-unlock:hover { background: var(--row-alt); }
.v-lockmsg { font-size: 12px; color: var(--acc-deep); font-weight: 600; }

/* ---------- 其它 ---------- */
.app-error {
  grid-column: 1 / -1; background: #fef2f2; border: 1px solid #fecaca; color: #b91c1c;
  border-radius: 10px; padding: 12px 16px; font-size: 13px;
}
.foot-note { grid-column: 1 / -1; text-align: center; font-size: 11px; color: var(--faint); }

@media (max-width: 1080px) {
  #region-main { grid-template-columns: 1fr; }
  .kbd-hints { display: none; }
}

input.content:
/* ============================================================
   选址决策台 · app（selection / weights / verdict 状态壳）
   状态所有权：selection → 应用壳（矩阵列 ↔ 地图点共享）；
              query(权重) → region-weights。
   ============================================================ */
(function () {
  'use strict';

  var $ = function (s, r) { return (r || document).querySelector(s); };
  var svg = $('#map');
  var tableWrap = $('#matrix-wrap');
  var weightsBox = $('#weights');
  var verdictBox = $('#region-verdict');
  var mapInfo = $('#map-info');
  var chip = $('#w-chip');

  var DEFAULT_W = {};
  CRITERIA.forEach(function (c) { DEFAULT_W[c.id] = c.w; });

  var state = {
    sel: null,      // 选中候选（矩阵列与地图点联动）
    locked: null,   // 锁定的最终选择
    weights: Object.assign({}, DEFAULT_W),
  };

  /* ---------- 评分模型 ---------- */
  // 各准则按三案极值归一为 0–100（better: low → 越小越优）
  function normScores() {
    var out = {};
    CRITERIA.forEach(function (c) {
      var vs = SITES.map(function (s) { return s.vals[c.id]; });
      var min = Math.min.apply(null, vs), max = Math.max.apply(null, vs);
      out[c.id] = {};
      SITES.forEach(function (s) {
        out[c.id][s.id] = (max === min) ? 50 :
          (c.better === 'low' ? (max - s.vals[c.id]) : (s.vals[c.id] - min)) / (max - min) * 100;
      });
    });
    return out;
  }

  function wSum() {
    return CRITERIA.reduce(function (a, c) { return a + (state.weights[c.id] || 0); }, 0);
  }

  // 返回 {siteId: {fit, rank, scores}}；无可用药重时 fit=null
  function computeFit() {
    var ns = normScores();
    var sum = wSum();
    var fits = {};
    SITES.forEach(function (s) {
      var f = null;
      if (sum > 0) {
        f = 0;
        CRITERIA.forEach(function (c) { f += ns[c.id][s.id] * (state.weights[c.id] || 0); });
        f = Math.round(f / sum);
      }
      fits[s.id] = { fit: f, scores: ns };
    });
    var order = SITES.slice().sort(function (a, b) { return (fits[b.id].fit || -1) - (fits[a.id].fit || -1); });
    order.forEach(function (s, i) { fits[s.id].rank = (fits[s.id].fit == null) ? 0 : i + 1; });
    return fits;
  }

  function leaderInfo(fits) {
    if (wSum() === 0) return null;
    var a = SITES[0], b = SITES[1];
    if ((fits[b.id].fit || 0) > (fits[a.id].fit || 0)) { var t = a; a = b; b = t; }
    for (var i = 2; i < SITES.length; i++) if ((fits[SITES[i].id].fit || 0) > (fits[a.id].fit || 0)) { b = a; a = SITES[i]; }
    else if ((fits[SITES[i].id].fit || 0) > (fits[b.id].fit || 0)) { b = SITES[i]; }
    return { lead: a, second: b };
  }

  // 领先者相对第二名的关键差距准则（加权分差最大者）
  function keyDriver(fits, lead, second) {
    var best = null;
    CRITERIA.forEach(function (c) {
      var d = (state.weights[c.id] || 0) * (fits[lead.id].scores[c.id][lead.id] - fits[lead.id].scores[c.id][second.id]);
      if (!best || d > best.d) best = { c: c, d: d };
    });
    if (!best || best.d <= 0) return null;
    return {
      label: best.c.label,
      a: best.c.fmt(lead.vals[best.c.id]),
      b: best.c.fmt(second.vals[best.c.id]),
    };
  }

  function crit(cId) { return CRITERIA.filter(function (c) { return c.id === cId; })[0]; }
  function site(sId) { return SITES.filter(function (s) { return s.id === sId; })[0]; }
  function esc(s) { return String(s).replace(/[&<>"]/g, function (m) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[m]; }); }

  /* ---------- 比较矩阵（主工作面） ---------- */
  function buildMatrix() {
    var h = '<colgroup><col class="c-label"><col span="' + SITES.length + '"></colgroup>';
    h += '<thead><tr><th class="rowh" scope="col">比较准则</th>';
    SITES.forEach(function (s) {
      h += '<th class="col" scope="col" data-col="' + s.id + '">' +
        '<button type="button" class="col-btn" data-site="' + s.id + '" aria-pressed="false" ' +
        'title="选中候选 ' + esc(s.key) + '（与地图点联动）">' +
        '<span class="site-key">' + esc(s.key) + '</span><span class="site-name">' + esc(s.name) + '</span>' +
        '<span class="site-addr">' + esc(s.addr) + ' · ' + esc(s.kind) + '</span>' +
        '<span data-chip></span></button></th>';
    });
    h += '</tr></thead><tbody>';

    h += '<tr class="row-fit"><th class="rowh" scope="row">契合分<span class="u">0–100 · 权重加权</span></th>';
    SITES.forEach(function (s) { h += '<td data-cell="fit:' + s.id + '" data-col="' + s.id + '"></td>'; });
    h += '</tr>';

    CRITERIA.forEach(function (c) {
      h += '<tr data-crit="' + c.id + '"><th class="rowh" scope="row">' + esc(c.label) + '<span class="u">' + esc(c.unit) + '</span></th>';
      SITES.forEach(function (s) { h += '<td data-cell="crit:' + c.id + ':' + s.id + '" data-col="' + s.id + '"></td>'; });
      h += '</tr>';
    });

    h += '<tr><th class="rowh" scope="row">预估月租<span class="u">面积 × 单价 × 30 天</span></th>';
    SITES.forEach(function (s) { h += '<td class="cell-arch" data-cell="arch:' + s.id + '" data-col="' + s.id + '"></td>'; });
    h += '</tr>';

    h += '<tr><th class="rowh" scope="row">一句话点评</th>';
    SITES.forEach(function (s) { h += '<td class="cell-note" data-cell="note:' + s.id + '" data-col="' + s.id + '">' + esc(s.note) + '</td>'; });
    h += '</tr>';

    h += '</tbody>';
    tableWrap.innerHTML = '<table aria-label="候选铺位比较矩阵">' + h + '</table>';
  }

  function renderMatrix(fits) {
    var table = $('table', tableWrap);
    var hasSel = !!state.sel, locked = state.locked;
    table.classList.toggle('is-locked-col', !!locked);

    SITES.forEach(function (s) {
      var f = fits[s.id];
      var isSel = state.sel === s.id;
      var isBestFit = (f.rank === 1 && f.fit != null);

      // 列头
      var th = $('th.col[data-col="' + s.id + '"]', table);
      th.classList.toggle('is-sel', isSel);
      th.classList.toggle('is-locked-col', locked === s.id);
      $('button.col-btn', th).setAttribute('aria-pressed', isSel ? 'true' : 'false');
      $('[data-chip]', th).innerHTML =
        (isBestFit && !locked ? '<span class="chip-lead">领先</span>' : '') +
        (locked === s.id ? '<span class="chip-lock">已锁定</span>' : '');

      // 契合分
      var fitTd = $('[data-cell="fit:' + s.id + '"]', table);
      fitTd.className = (f.rank === 1 && f.fit != null ? 'rank1 ' : '') + (isSel ? 'is-sel ' : '');
      fitTd.innerHTML = (f.fit == null)
        ? '<span class="fit-empty">— 待设权重</span>'
        : '<span class="fit-score">' + f.fit + '</span><span class="fit-rank" title="名次">' + f.rank + '</span>';

      // 准则行：数值 + 行内微条形 + 行最优徽标
      CRITERIA.forEach(function (c) {
        var td = $('[data-cell="crit:' + c.id + ':' + s.id + '"]', table);
        var sc = f.scores[c.id][s.id];
        var isBest = SITES.every(function (o) { return sc >= f.scores[c.id][o.id] - 1e-9; }) &&
          (SITES.length < 2 || sc > Math.max.apply(null, SITES.filter(function (o) { return o.id !== s.id; })
            .map(function (o) { return f.scores[c.id][o.id]; })));
        td.className = (isBest ? 'best ' : '') + (isSel ? 'is-sel' : '');
        td.innerHTML = '<span class="val">' + esc(c.fmt(s.vals[c.id])) + '</span>' +
          (isBest ? '<span class="badge-best">优</span>' : '') +
          '<div class="bar" aria-hidden="true"><i style="width:' + Math.round(sc) + '%"></i></div>';
      });

      // 档案
      var arch = $('[data-cell="arch:' + s.id + '"]', table);
      arch.className = 'cell-arch' + (isSel ? ' is-sel' : '');
      arch.innerHTML = '≈ <b>' + monthlyRentWan(s).toFixed(1) + '</b> 万/月（' + s.area + '㎡ × ' +
        esc(crit('rent').fmt(s.vals.rent)) + '）';

      var noteTd = $('[data-cell="note:' + s.id + '"]', table);
      noteTd.classList.toggle('is-sel', isSel);
    });
  }

  /* ---------- 商圈地图：选中联动 + 行悬停关联 ---------- */
  var REL = { commute: ['.m-metro', '.m-anchor'], traffic: ['.m-flow'], rival: ['.m-rivals'] };

  function renderMap(fits) {
    var lead = leaderInfo(fits);
    SITES.forEach(function (s) {
      var pin = $('.pin[data-site="' + s.id + '"]', svg);
      pin.classList.toggle('is-sel', state.sel === s.id);
      pin.classList.toggle('is-lead', !!lead && lead.lead.id === s.id && !state.locked);
      pin.classList.toggle('is-locked', state.locked === s.id);
      pin.setAttribute('aria-pressed', state.sel === s.id ? 'true' : 'false');
    });

    var wl = $('#walk-line'), wlt = $('#walk-label');
    if (state.sel) {
      var s = site(state.sel);
      var x1 = s.pinXY[0], y1 = s.pinXY[1], x2 = s.stationXY[0], y2 = s.stationXY[1];
      wl.setAttribute('x1', x1); wl.setAttribute('y1', y1);
      wl.setAttribute('x2', x2); wl.setAttribute('y2', y2);
      wl.setAttribute('visibility', 'visible');
      wlt.setAttribute('x', (x1 + x2) / 2); wlt.setAttribute('y', (y1 + y2) / 2 - 5);
      wlt.setAttribute('text-anchor', 'middle');
      wlt.textContent = '步行 ' + s.walkToStation + '′';
      wlt.setAttribute('visibility', 'visible');
      mapInfo.innerHTML = '已选 <strong>' + esc(s.key) + ' ' + esc(s.name) + '</strong> — 距' +
        esc(s.station) + '步行 ' + s.walkToStation + '′ · 至江北商务区 ' + s.vals.commute + '′（均步行）';
    } else {
      wl.setAttribute('visibility', 'hidden'); wlt.setAttribute('visibility', 'hidden');
      mapInfo.innerHTML = '点击候选点或右侧列头，双向联动选中。';
    }
  }

  function bindMapHover() {
    var table = $('table', tableWrap);
    table.addEventListener('mouseover', function (e) {
      var tr = e.target.closest('tr[data-crit]');
      if (!tr || tr === bindMapHover._last) return;
      clearHot(); bindMapHover._last = tr;
      var rels = REL[tr.getAttribute('data-crit')] || [];
      if (!rels.length) return;
      svg.classList.add('has-hot');
      rels.forEach(function (sel) { var g = $(sel, svg); if (g) g.classList.add('hot'); });
    });
    table.addEventListener('mouseout', function (e) {
      if (e.target.closest('tr[data-crit]')) { clearHot(); bindMapHover._last = null; }
    });
    function clearHot() {
      svg.classList.remove('has-hot');
      Array.prototype.forEach.call(svg.querySelectorAll('.hot'), function (g) { g.classList.remove('hot'); });
    }
  }

  /* ---------- 权重轨（query 状态所有者） ---------- */
  function buildWeights() {
    weightsBox.innerHTML = CRITERIA.map(function (c) {
      return '<div class="w-item">' +
        '<label for="w-' + c.id + '">' + esc(c.label) + '<span class="w-unit">' + esc(c.unit) + '</span></label>' +
        '<output id="wo-' + c.id + '" for="w-' + c.id + '">' + state.weights[c.id] + '</output>' +
        '<input type="range" id="w-' + c.id + '" min="0" max="5" step="1" value="' + state.weights[c.id] + '" ' +
        'aria-label="准则权重：' + esc(c.label) + '（0–5）">' +
        '</div>';
    }).join('');
    weightsBox.addEventListener('input', function (e) {
      var id = String(e.target.id || '').replace('w-', '');
      if (!crit(id)) return;
      state.weights[id] = +e.target.value;
      updateWeightsMeta();
      render();
    });
  }

  function updateWeightsMeta() {
    CRITERIA.forEach(function (c) {
      var out = $('#wo-' + c.id); if (out) out.value = state.weights[c.id];
      var inp = $('#w-' + c.id); if (inp && +inp.value !== state.weights[c.id]) inp.value = state.weights[c.id];
    });
    var custom = CRITERIA.some(function (c) { return state.weights[c.id] !== DEFAULT_W[c.id]; });
    chip.hidden = !custom;
  }

  function resetWeights() {
    state.weights = Object.assign({}, DEFAULT_W);
    updateWeightsMeta(); render();
  }

  /* ---------- 决策结论条（常驻） ---------- */
  function renderVerdict(fits) {
    var lead = leaderInfo(fits);
    var acts = '';
    if (state.locked) {
      var s = site(state.locked);
      var f = fits[s.id];
      var top = CRITERIA.slice().sort(function (a, b) {
        return (f.scores[b.id][s.id] * (state.weights[b.id] || 0)) - (f.scores[a.id][s.id] * (state.weights[a.id] || 0));
      })[0];
      verdictBox.innerHTML =
        '<span class="v-lockmsg">🔒 已锁定</span>' +
        '<span class="v-leader"><strong>' + esc(s.key) + ' ' + esc(s.name) + '</strong></span>' +
        '<span class="v-detail">契合 <b>' + (f.fit == null ? '—' : f.fit) + '</b> 分 · 最强项 <b>' + esc(top.label) + '</b>' +
        ' · 距' + esc(s.station) + '步行 ' + s.walkToStation + '′ · ' + esc(s.kind) + '</span>' +
        '<span class="v-actions"><button type="button" class="btn-unlock" data-act="unlock">改选 / 解锁</button></span>';
    } else if (lead) {
      var d = keyDriver(fits, lead.lead, lead.second);
      var driverTxt = d ? ' · 关键差距：<b>' + esc(d.label) + '</b>（' + esc(d.a) + ' vs ' + esc(d.b) + '）'
        : (lead.lead.fit === lead.second.fit ? ' · 两案并列，调整权重以突出侧重' : '');
      verdictBox.innerHTML =
        '<span class="v-leader">当前领先：<strong>' + esc(lead.lead.key) + ' ' + esc(lead.lead.name) + '</strong></span>' +
        '<span class="v-detail">契合 <b>' + lead.lead.fit + '</b> 分 · 领先第 2 名（' + esc(lead.second.key) + ' ' +
        esc(lead.second.name) + '）<b>' + (lead.lead.fit - lead.second.fit) + '</b> 分' + driverTxt + '</span>' +
        '<span class="v-actions"><button type="button" class="btn-primary" data-act="lock">锁定选择：' +
        esc(lead.lead.key) + ' ' + esc(lead.lead.name) + '</button></span>';
    } else {
      verdictBox.innerHTML =
        '<span class="v-leader">暂无有效评分</span>' +
        '<span class="v-detail">请至少为 <b>一项准则</b> 设置大于 0 的权重，即可计算契合分并得出领先者。</span>' +
        '<span class="v-actions"><button type="button" class="btn-primary" data-act="lock" disabled>锁定选择</button></span>';
    }
  }

  function toggleLock() {
    if (state.locked) { state.locked = null; }
    else {
      var fits = computeFit();
      var lead = leaderInfo(fits);
      if (!lead) return;
      state.locked = state.sel || lead.lead.id;
    }
    render();
  }

  /* ---------- 总渲染 ---------- */
  function render() {
    var fits = computeFit();
    renderMatrix(fits);
    renderMap(fits);
    renderVerdict(fits);
  }

  function selectSite(id) {
    state.sel = (state.sel === id) ? null : id;
    render();
  }

  /* ---------- 事件 ---------- */
  function bindEvents() {
    // 列头点击（事件委托，重渲染后仍有效）
    tableWrap.addEventListener('click', function (e) {
      var btn = e.target.closest('button.col-btn');
      if (btn) selectSite(btn.getAttribute('data-site'));
    });
    // 地图候选点
    svg.addEventListener('click', function (e) {
      var pin = e.target.closest('.pin');
      if (pin) selectSite(pin.getAttribute('data-site'));
    });
    svg.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      var pin = e.target.closest('.pin');
      if (pin) { e.preventDefault(); selectSite(pin.getAttribute('data-site')); }
    });
    // 结论条动作
    verdictBox.addEventListener('click', function (e) {
      var b = e.target.closest('[data-act]');
      if (!b) return;
      if (b.getAttribute('data-act') === 'lock') toggleLock();
      if (b.getAttribute('data-act') === 'unlock') { state.locked = null; render(); }
    });
    $('#w-reset').addEventListener('click', resetWeights);

    // 键盘契约：←/→ 切换 · 1–3 选中 · L 锁定 · R 重置权重
    document.addEventListener('keydown', function (e) {
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      var tag = e.target && e.target.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
      var ids = SITES.map(function (s) { return s.id; });
      if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
        e.preventDefault();
        var i = ids.indexOf(state.sel);
        i = e.key === 'ArrowRight' ? (i + 1) % ids.length : (i - 1 + ids.length) % ids.length;
        if (i === 0 && state.sel == null && e.key === 'ArrowLeft') i = ids.length - 1;
        state.sel = ids[i < 0 ? 0 : i];
        render();
      } else if (/^[1-9]$/.test(e.key) && +e.key <= ids.length) {
        selectSite(ids[+e.key - 1]);
      } else if (e.key === 'l' || e.key === 'L') {
        toggleLock();
      } else if (e.key === 'r' || e.key === 'R') {
        resetWeights();
      }
    });
  }

  /* ---------- 初始化（同步、无加载态） ---------- */
  function init() {
    if (!Array.isArray(SITES) || SITES.length === 0 || !Array.isArray(CRITERIA) || CRITERIA.length === 0) {
      var err = $('#app-error');
      err.hidden = false;
      err.textContent = '候选数据缺失：无法进行选址比较。请检查 data.js。';
      $('#region-main').style.display = 'none';
      verdictBox.style.display = 'none';
      return;
    }
    $('#data-note').textContent = SCENARIO.note;
    buildMatrix();
    buildWeights();
    bindMapHover();
    bindEvents();
    updateWeightsMeta();
    render();   // 首帧即 ready：无骨架、无 loading
  }

  try { init(); } catch (err) {
    var box = $('#app-error');
    box.hidden = false;
    box.textContent = '初始化失败：' + (err && err.message ? err.message : err);
  }
})();

