2	import { createServer } from "node:http";
3	import { readFile, stat, realpath } from "node:fs/promises";
4	import { extname, isAbsolute, join, resolve, relative } from "node:path";
5	import { spawn, type ChildProcess } from "node:child_process";
6	import { chromium } from "playwright";
7	import { ARTIFACT_CHECK_DEFAULT_SEVERITY, ARTIFACT_CHECK_IDS, MeasurementReceiptSchema, captureImplementation, captureContracts, isMeasurementExcluded, type ArtifactCheckId } from "prax-validator";
8	import type { CheckOutcome } from "./checks/layout.overflow.js";
9	import { run as layoutOverflow } from "./checks/layout.overflow.js";
10	import { run as layoutResponsiveCollision } from "./checks/layout.responsive_collision.js";
11	import { run as textTruncation } from "./checks/text.truncation.js";
12	import { run as a11yContrast } from "./checks/a11y.contrast.js";
13	import { run as a11yFocusOrder } from "./checks/a11y.focus_order.js";
14	import { run as a11yTargetSize } from "./checks/a11y.target_size.js";
15	import { run as typeMinProjectedSize } from "./checks/type.min_projected_size.js";
16	import { writeReceiptAtomically } from "./receipt.js";
17	import { assertTargetUrl, navigateTarget, observeTargetFailures } from "./target-readiness.js";
18	
19	export interface RunnerViewport {
20	  width: number;
21	  height: number;
22	  label?: string | undefined;
23	}
24	
25	export interface RunMeasurementOptions {
26	  appDir: string; // app root; dist/ presence selects vite preview, otherwise a static server
27	  outDir: string; // session/output directory; evidence lands under validation-evidence/
28	  viewports: RunnerViewport[];
29	  entry?: string | undefined; // URL path of the measured page; default "/"
30	  serve?: string | undefined; // reuse an already-running base URL instead of spawning a server
31	  buildRef?: string | null | undefined;
32	  readySelector?: string | undefined;
33	  readyTimeoutMs?: number | undefined;
34	  sessionId?: string | undefined;
35	  scenario?: string | undefined;
36	}
37	
38	type CheckModule = { id: ArtifactCheckId; run: (page: import("playwright").Page, ctx: { viewport: RunnerViewport; screenshotDir: string }) => Promise<CheckOutcome> };
39	
40	const CHECKS: CheckModule[] = [
41	  { id: "layout.overflow", run: layoutOverflow },
42	  { id: "layout.responsive_collision", run: layoutResponsiveCollision },
43	  { id: "text.truncation", run: textTruncation },
44	  { id: "a11y.contrast", run: a11yContrast },
45	  { id: "a11y.focus_order", run: a11yFocusOrder },
46	  { id: "a11y.target_size", run: a11yTargetSize },
47	  { id: "type.min_projected_size", run: typeMinProjectedSize },
48	];
49	
50	const TOOL_VERSION = "0.2.0";
51	
52	const MIME_TYPES: Record<string, string> = {
53	  ".html": "text/html; charset=utf-8",
54	  ".css": "text/css; charset=utf-8",
55	  ".js": "text/javascript; charset=utf-8",
56	  ".mjs": "text/javascript; charset=utf-8",
57	  ".json": "application/json; charset=utf-8",
58	  ".svg": "image/svg+xml",
59	  ".png": "image/png",
60	  ".jpg": "image/jpeg",
61	  ".jpeg": "image/jpeg",
62	  ".gif": "image/gif",
63	  ".webp": "image/webp",
64	  ".ico": "image/x-icon",
65	  ".woff": "font/woff",
66	  ".woff2": "font/woff2",
67	};
68	
69	interface RunningServer {
70	  baseUrl: string;
71	  close: () => Promise<void>;
72	}
73	
74	async function startStaticServer(root: string): Promise<RunningServer> {
75	  const server = createServer(async (request, response) => {
76	    try {
77	      const url = new URL(request.url ?? "/", "http://localhost");
78	      let pathName = decodeURIComponent(url.pathname);
79	      if (pathName.endsWith("/")) pathName = `${pathName}index.html`;
80	      const target = resolve(root, `.${pathName}`);
81	      const contained = (path: string) => {
82	        const child = relative(root, path);
83	        return child !== ".." && !child.startsWith("../") && !child.startsWith("..\\") && !isAbsolute(child);
84	      };
85	      if (!contained(target) || isMeasurementExcluded(relative(root, target))) {
86	        response.writeHead(403).end("forbidden");
87	        return;
88	      }
89	      const stats = await stat(target);
90	      const filePath = await realpath(stats.isDirectory() ? join(target, "index.html") : target);
91	      if (!contained(filePath) || isMeasurementExcluded(relative(root, filePath))) {
92	        response.writeHead(403).end("forbidden");
93	        return;
94	      }
95	      const content = await readFile(filePath);
96	      response.writeHead(200, { "content-type": MIME_TYPES[extname(filePath)] ?? "application/octet-stream" });
97	      response.end(content);
98	    } catch {
99	      response.writeHead(404).end("not found");
100	    }
101	  });
102	  await new Promise<void>((resolvePromise) => server.listen(0, "127.0.0.1", resolvePromise));
103	  const address = server.address();
104	  const port = typeof address === "object" && address !== null ? address.port : 0;
105	  return {
106	    baseUrl: `http://127.0.0.1:${port}/`,
107	    close: () => new Promise<void>((resolvePromise) => server.close(() => resolvePromise())),
108	  };
109	}
110	
111	async function startVitePreview(appDir: string): Promise<RunningServer> {
112	  const port = 20000 + Math.floor(Math.random() * 20000);
113	  const viteBin = join(process.cwd(), "node_modules", "vite", "bin", "vite.js");
114	  const server: ChildProcess = spawn(
115	    process.execPath,
116	    [viteBin, "preview", "--port", String(port), "--strictPort", "--host", "127.0.0.1"],
117	    { cwd: appDir, stdio: ["ignore", "pipe", "pipe"] },
118	  );
119	  const baseUrl = `http://127.0.0.1:${port}/`;
120	  for (let attempt = 0; attempt < 40; attempt += 1) {
121	    try {
122	      const response = await fetch(baseUrl, { signal: AbortSignal.timeout(1000) });
123	      if (response.ok) break;
124	    } catch {
125	      // not up yet
126	    }
127	    if (attempt === 39) {
128	      server.kill();
129	      throw new Error("vite preview did not come up within 20s");
130	    }
131	    await new Promise((resolveDelay) => setTimeout(resolveDelay, 500));
132	  }
133	  return {
134	    baseUrl,
135	    close: () =>
136	      new Promise<void>((resolvePromise) => {
137	        server.once("exit", () => resolvePromise());
138	        server.kill();
139	      }),
140	  };
141	}
142	
143	function mergeOutcomes(id: ArtifactCheckId, outcomes: CheckOutcome[]): CheckOutcome {
144	  const failing = outcomes.find((outcome) => outcome.status === "fail");
145	  const base = failing ?? outcomes.find((outcome) => outcome.status === "skipped") ?? outcomes[0]!;
146	  if (outcomes.length === 1) return base;
147	  const perViewport = outcomes.map((outcome) => ({
148	    viewport: (outcome.measured as Record<string, unknown>).viewport ?? null,
149	    status: outcome.status,
150	  }));
151	  const status = failing !== undefined ? "fail" : outcomes.some((o) => o.status === "skipped") ? "skipped" : "pass";
152	  return {
153	    ...base,
154	    id,
155	    status,
156	    measured: { ...(base.measured as Record<string, unknown>), per_viewport: perViewport },
157	    evidence_refs: outcomes.flatMap((outcome) => outcome.evidence_refs ?? []),
158	  };
159	}
160	
161	function skippedOutcome(id: ArtifactCheckId, reason: string): CheckOutcome {
162	  return {
163	    id,
164	    status: "skipped",
165	    severity: ARTIFACT_CHECK_DEFAULT_SEVERITY[id],
166	    subject: `check ${id}`,
167	    measured: {},
168	    threshold: {},
169	    evidence_refs: [],
170	    supported_fixes: [],
171	    reason,
172	  };
173	}
174	
175	/**
176	 * Orchestration (spec §5.1): serve the app (vite preview when a build is
177	 * present, static server otherwise), then for each viewport × each check run
178	 * on a fresh page. Evidence sha256 is recomputed by the runner from the files
179	 * on disk — values declared by checks are never trusted. Environment failures
180	 * degrade honestly to skipped-with-reason, never guessed fixes.
181	 */
182	export async function runMeasurement(options: RunMeasurementOptions): Promise<string> {
183	  if (options.readyTimeoutMs !== undefined && (!Number.isInteger(options.readyTimeoutMs) || options.readyTimeoutMs <= 0 || options.readyTimeoutMs > 60_000)) {
184	    throw new Error("readyTimeoutMs must be an integer from 1 to 60000");
185	  }
186	  const runId = randomUUID();
187	  const runDirectory = join(options.outDir, "validation-evidence", runId);
188	  const implementation = await captureImplementation(options.appDir);
189	  const contracts = await captureContracts(options.outDir);
190	  const appRoot = implementation.root;
191	  const hasBuild = await stat(join(options.appDir, "dist")).then((stats) => stats.isDirectory()).catch(() => false);
192	  const entry = options.entry ?? "/";
193	  if (!entry.startsWith("/") || entry.startsWith("//") || /[\\\s]/.test(entry)) throw new Error("entry must be a root-relative URL path");
194	  if (options.viewports.length === 0 || options.viewports.some((v) => !Number.isInteger(v.width) || !Number.isInteger(v.height) || v.width <= 0 || v.height <= 0)) {
195	    throw new Error("at least one positive integer viewport is required");
196	  }
197	  const invalidTarget = new Set<string>();
198	
199	  let server: RunningServer | undefined;
200	  let baseUrl: string;
201	  if (options.serve !== undefined) {
202	    baseUrl = options.serve;
203	  } else {
204	    server = hasBuild ? await startVitePreview(appRoot) : await startStaticServer(appRoot);
205	    baseUrl = server.baseUrl;
206	  }
207	
208	  const outcomesByCheck = new Map<ArtifactCheckId, CheckOutcome[]>();
209	  let environmentFailure: string | undefined;
210	  try {
211	    const browser = await chromium.launch();
212	    try {
213	      for (const [viewportIndex, viewport] of options.viewports.entries()) {
214	        for (const check of CHECKS) {
215	          const screenshotDir = join(runDirectory, `viewport-${viewportIndex}`, check.id);
216	          const page = await browser.newPage({ viewport: { width: viewport.width, height: viewport.height } });
217	          const targetIssues = observeTargetFailures(page);
218	          const targetUrl = new URL(entry, baseUrl).href;
219	          try {
220	            try {
221	              await navigateTarget(page, targetUrl, options);
222	            } catch (error) {
223	              targetIssues.push(error instanceof Error ? error.message : String(error));
224	            }
225	            if (targetIssues.length > 0) throw new Error(`invalid_target: ${targetIssues.join("; ")}`);
226	            const outcome = await check.run(page, { viewport, screenshotDir });
227	            if (targetIssues.length > 0) throw new Error(`invalid_target: ${targetIssues.join("; ")}`);
228	            for (const ref of outcome.evidence_refs) {
229	              const fileName = ref.ref.slice("validation-evidence/".length);
230	              if (!ref.ref.startsWith("validation-evidence/") || fileName.includes("/") || fileName.includes("\\") || fileName === "..") {
231	                throw new Error(`unexpected check evidence reference: ${ref.ref}`);
232	              }
233	              ref.ref = `${relative(options.outDir, screenshotDir).replaceAll("\\", "/")}/${fileName}`;
234	            }
235	            const bucket = outcomesByCheck.get(check.id) ?? [];
236	            bucket.push(outcome);
237	            outcomesByCheck.set(check.id, bucket);
238	          } catch (error) {
239	            const bucket = outcomesByCheck.get(check.id) ?? [];
240	            bucket.push(
241	              skippedOutcome(check.id, `check execution failed: ${error instanceof Error ? error.message : String(error)}`),
242	            );
243	            outcomesByCheck.set(check.id, bucket);
244	          } finally {
245	            try {
246	              assertTargetUrl(page, targetUrl);
247	            } catch (error) {
248	              targetIssues.push(error instanceof Error ? error.message : String(error));
249	            }
250	            for (const issue of targetIssues) invalidTarget.add(issue);
251	            await page.close();
252	          }
253	        }
254	      }
255	    } finally {
256	      await browser.close();
257	    }
258	  } catch (error) {
259	    environmentFailure = `browser environment unavailable: ${error instanceof Error ? error.message : String(error)}`;
260	    invalidTarget.add(environmentFailure);
261	    for (const id of ARTIFACT_CHECK_IDS) {
262	      outcomesByCheck.set(id, [skippedOutcome(id, environmentFailure)]);
263	    }
264	  } finally {
265	    await server?.close();
266	  }
267	
268	  try {
269	    if ((await captureImplementation(appRoot)).digest !== implementation.digest) invalidTarget.add("implementation changed during measurement");
270	    if (JSON.stringify(await captureContracts(options.outDir)) !== JSON.stringify(contracts)) invalidTarget.add("design contracts changed during measurement");
271	  } catch (error) {
272	    invalidTarget.add(`content binding unavailable: ${error instanceof Error ? error.message : String(error)}`);
273	  }
274	
275	  const checks = ARTIFACT_CHECK_IDS.map((id) => {
276	    if (invalidTarget.size > 0) return skippedOutcome(id, `invalid_target: ${[...invalidTarget].join("; ")}`);
277	    const outcomes = outcomesByCheck.get(id) ?? [skippedOutcome(id, "check did not run")];
278	    return mergeOutcomes(id, outcomes);
279	  });
280	
281	  // the runner recomputes every evidence digest from the bytes on disk
282	  for (const check of checks) {
283	    for (const ref of check.evidence_refs ?? []) {
284	      const filePath = join(options.outDir, ref.ref);
285	      ref.sha256 = await readFile(filePath)
286	        .then((bytes) => createHash("sha256").update(bytes).digest("hex"))
287	        .catch(() => {
288	          throw new Error(`evidence file declared by check ${check.id} is missing on disk: ${ref.ref}`);
289	        });
290	    }
291	  }
292	
293	  const receipt = MeasurementReceiptSchema.parse({
294	    receipt_version: "0.2",
295	    tool: { name: "prax-measure", version: TOOL_VERSION },
296	    target: { app_root: appRoot, base_url: baseUrl, build_ref: options.buildRef ?? null },
297	    binding: {
298	      run_id: runId,
299	      entry,
300	      scenario: options.scenario ?? "entry",
301	      implementation: { ...implementation, kind: options.serve !== undefined || hasBuild ? "local_source_association" : "static_tree" },
302	      session_id: options.sessionId ?? null,
303	      contract_digests: contracts,
304	    },
305	    target_validation: {
306	      status: invalidTarget.size === 0 ? "valid" : "invalid",
307	      issues: [...invalidTarget],
308	      readiness: options.readySelector === undefined ? "document" : "selector",
309	      ready_selector: options.readySelector ?? null,
310	    },
311	    run_at: new Date().toISOString(),
312	    viewport_matrix: options.viewports.map((viewport) => ({
313	      width: viewport.width,
314	      height: viewport.height,
315	      ...(viewport.label === undefined ? {} : { label: viewport.label }),
316	    })),
317	    checks,
318	    summary: {
319	      pass: checks.filter((check) => check.status === "pass").length,
