1	import { createHash } from "node:crypto";
2	import { mkdir, readFile } from "node:fs/promises";
3	import { join } from "node:path";
4	import type { Page } from "playwright";
5	import { ARTIFACT_CHECK_DEFAULT_SEVERITY } from "prax-validator";
6	import type { MeasurementReceipt } from "prax-validator";
7	
8	export interface CheckContext {
9	  viewport: { width: number; height: number; label?: string | undefined };
10	  screenshotDir: string; // absolute; check writes PNGs here, refs are rebased by the runner
11	}
12	
13	export type CheckOutcome = MeasurementReceipt["checks"][number];
14	
15	const MAX_STOPS = 64;
16	
17	/**
18	 * a11y.focus_order (spec §5.3): sequential Tab walk (max 64 stops). Every
19	 * focused element must carry a visible indicator (outline or box-shadow —
20	 * background-only changes do not count), and consecutive stops that move
21	 * backwards in the visual reading order (bounding-box, row-banded) are
22	 * reported as inversions.
23	 */
24	export async function run(page: Page, ctx: CheckContext): Promise<CheckOutcome> {
25	  const viewportLabel = ctx.viewport.label ?? `${ctx.viewport.width}x${ctx.viewport.height}`;
26	
27	  const stops: Array<{ selector: string; rect: { x: number; y: number; width: number; height: number } }> = [];
28	  const missingIndicators: string[] = [];
29	  let incomplete: string | undefined = `incomplete focus traversal: reached ${MAX_STOPS} stops`;
30	  const visited = await page.evaluateHandle(() => new WeakSet<Element>());
31	  try {
32	    for (let index = 0; index < MAX_STOPS; index += 1) {
33	      await page.keyboard.press("Tab");
34	      const stop = await page.evaluate((seen) => {
